create or replace function public.dd_fos_validate_state_transition() returns trigger language plpgsql as $$ begin if new.status=old.status then return new; end if; if old.status='INSTANTIATED' and new.status not in ('OFFERED','CANCELLED') then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status='OFFERED' and new.status not in ('ACCEPTED','INSTANTIATED','CANCELLED') then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status='ACCEPTED' and new.status not in ('SCHEDULED','CANCELLED') then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status='SCHEDULED' and new.status not in ('EN_ROUTE','CANCELLED') then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status='EN_ROUTE' and new.status not in ('IN_PROGRESS','CANCELLED') then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status='IN_PROGRESS' and new.status not in ('SUBMITTED','CANCELLED') then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status='SUBMITTED' and new.status not in ('QA_REVIEW','CANCELLED') then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status='QA_REVIEW' and new.status not in ('QA_PASS','QA_FAIL') then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status='QA_FAIL' and new.status not in ('IN_PROGRESS','CANCELLED') then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status='QA_PASS' and new.status not in ('CUSTOMER_CLOSED','CANCELLED') then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status='CUSTOMER_CLOSED' and new.status<>'PAYABLE' then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status='PAYABLE' and new.status<>'PAID' then raise exception 'Invalid FOS transition: % -> %',old.status,new.status; elsif old.status in ('PAID','CANCELLED') then raise exception 'Terminal FOS state cannot be changed: %',old.status; end if; return new; end $$;
create or replace function public.dd_fos_append_work_order_event() returns trigger language plpgsql as $$ begin if TG_OP='INSERT' then insert into public.dd_work_order_event_history(work_order_id,actor_id,actor_type,event_type,previous_state,new_state,payload) values(new.id,auth.uid(),'SYSTEM','WORK_ORDER_CREATED',new.status,new.status,jsonb_build_object('work_order_number',new.work_order_number)); elseif new.status<>old.status then insert into public.dd_work_order_event_history(work_order_id,actor_id,actor_type,event_type,previous_state,new_state,payload) values(new.id,auth.uid(),'USER_OR_SYSTEM','STATE_CHANGED',old.status,new.status,'{}'::jsonb); end if; return new; end $$;
create or replace function public.dd_fos_immutable_event_history() returns trigger language plpgsql as $$ begin raise exception 'FOS event history is append-only'; end $$;
create or replace function public.dd_fos_qa_payable_gate() returns trigger language plpgsql as $$ declare v_change_order_total numeric(10,2):=0; v_base numeric(10,2):=0; v_travel numeric(10,2):=0; v_total numeric(10,2):=0; begin if new.status='QA_PASS' and old.status='QA_REVIEW' and new.primary_provider_id is not null then select coalesce(sum(provider_pay_delta),0) into v_change_order_total from public.dd_change_orders where work_order_id=new.id and status='APPROVED'; v_base:=coalesce(new.fos_base_authorized_amount,new.provider_pay_amount,0)*coalesce(new.fos_quantity_basis_count,1); v_travel:=coalesce(new.fos_travel_payout_allocation,new.travel_amount,0); v_total:=v_base+v_travel+v_change_order_total; insert into public.dd_accounts_payable_ledger(work_order_id,provider_id,base_payout_amount,travel_allowance,approved_change_order_addition,total_final_payable,is_cleared_for_payout) values(new.id,new.primary_provider_id,v_base,v_travel,v_change_order_total,v_total,false) on conflict(work_order_id) do nothing; new.fos_total_provider_payable_accrued:=v_total; end if; return new; end $$;
create or replace function public.dd_fos_payable_clearance() returns trigger language plpgsql as $$ begin if new.status='PAYABLE' and old.status='CUSTOMER_CLOSED' and new.primary_provider_id is not null then update public.dd_accounts_payable_ledger set is_cleared_for_payout=true where work_order_id=new.id; end if; if new.status='PAID' and old.status='PAYABLE' and new.primary_provider_id is not null then if not exists(select 1 from public.dd_accounts_payable_ledger where work_order_id=new.id and is_cleared_for_payout=true) then raise exception 'Provider payable is not cleared; cannot mark work order PAID'; end if; end if; return new; end $$;
